<script setup lang="ts">import{onMounted,ref}from'vue';import{wmApi}from'../api';import{statusLabel,newsStatus,type WmNews}from'@leadnews/shared';import{ElMessage,ElMessageBox}from'element-plus';const rows=ref<WmNews[]>([]),loading=ref(true);async function load(){loading.value=true;try{rows.value=(await wmApi.list()).records}finally{loading.value=false}}async function remove(row:WmNews){await ElMessageBox.confirm(`删除《${row.title}》？`);try{await wmApi.remove(row.id);await load()}catch(e:any){ElMessage.error(e.message)}}async function submit(row:WmNews){try{await wmApi.submit(row.id);ElMessage.success('已提交审核');await load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load)</script><template><section class="panel"><div class="toolbar"><h1 style="flex:1">我的稿件</h1><RouterLink to="/news/new"><el-button type="primary">新建稿件</el-button></RouterLink></div><el-table :data="rows" v-loading="loading"><el-table-column prop="title" label="标题" min-width="220"/><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="newsStatus[row.status]?.tone as any">{{statusLabel(row.status)}}</el-tag></template></el-table-column><el-table-column prop="publishTime" label="计划发布" width="180"/><el-table-column label="操作" width="230"><template #default="{row}"><RouterLink :to="`/news/${row.id}`"><el-button text>查看/编辑</el-button></RouterLink><el-button v-if="['DRAFT','REJECTED'].includes(row.status)" text @click="submit(row)">提交</el-button><el-button v-if="row.status==='DRAFT'" text type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div v-if="!loading&&!rows.length" class="empty">暂无稿件</div></section></template>
